  // ---- entra y sale, y lo que se quemó fue la entrada --------------------
  'ctx.logStamp': 'Un registro de estampado empareja lo que entró en la prensa con lo que salió de ella. Una línea conservó su salida y perdió lo que entró.',
  'ctx.logDye': 'El registro del tinte anota la concentración que entró y la que salió. Una línea perdió la de partida.',
  'ctx.logTuner': 'El registro del sintonizador empareja la frecuencia que le dieron con la que devolvió. Una línea tiene la devuelta y no la entregada.',
  'ctx.logMint': 'El registro de la ceca anota el cospel que fue al cuño y la moneda que salió. Una línea perdió el cospel.',
  'ctx.logSmelter': 'El registro de la fundición empareja la carga que entró con el metal que salió. Una línea conservó el metal y perdió la carga.',

  // ---- algo que empieza en b y pierde a de sí mismo por minuto -----------
